diff --git a/repro60573/check.js b/repro60573/check.js
new file mode 100644
index 000000000..754591d68
--- /dev/null
+++ b/repro60573/check.js
@@ -0,0 +1,20 @@
+// Exits non-zero while `Test` is not `{ prop1: "hello"; }` (the expected type from the report).
+// Usage (from repo root): node repro60573/check.js [path/to/typescript.js] [input.ts]
+const path = require("path");
+const ts = require(path.resolve(process.argv[2] || "built/local/typescript.js"));
+const file = path.resolve(process.argv[3] || path.join(__dirname, "input.ts"));
+const program = ts.createProgram([file], { strict: true, noEmit: true, types: [], target: ts.ScriptTarget.ES2022 });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+let alias;
+sf.forEachChild(n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") alias = n; });
+const type = checker.getTypeAtLocation(alias.name);
+const actual = checker.typeToString(type, undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias);
+const expected = `{ prop1: "hello"; }`;
+console.log(`TypeScript ${ts.version}`);
+console.log(`Expected: type Test = ${expected}`);
+console.log(`Actual:   type Test = ${actual}`);
+const diags = ts.getPreEmitDiagnostics(program);
+if (diags.length) console.log("Diagnostics:\n" + ts.formatDiagnostics(diags, { getCanonicalFileName: f => f, getCurrentDirectory: () => process.cwd(), getNewLine: () => "\n" }));
+if (actual !== expected) { console.error("FAIL: Test is not the expected type"); process.exit(1); }
+console.log("PASS");
diff --git a/repro60573/input.ts b/repro60573/input.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro60573/input.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
